import type React from 'react';

import './AiProvenanceFrame.css';

export interface AiProvenanceFrameProps {
  /** The AI-produced content to frame. */
  children: React.ReactNode;
  /** Provenance label, e.g. "Generated by Hive AI". Defaults to "AI-generated". */
  label?: string;
  /** Show the "verify before acting" caveat footer (default true). */
  caveat?: boolean;
  /** Override the caveat text. */
  caveatText?: string;
  /**
   * Visual weight of the frame:
   *  - `rule` (default): a violet left rule + header label (matches AiVerdictCard/ReasoningStream).
   *  - `subtle`: just a small header label, no border — for inline AI text inside another surface.
   */
  variant?: 'rule' | 'subtle';
  className?: string;
}

/**
 * AiProvenanceFrame — the single primitive that codifies the AI provenance rule (design §5a/C):
 * any surface produced by an AI agent is wrapped so it is unmistakably marked as AI output, in
 * `--ha-intelligence-primary`, with an optional "verify before acting" caveat. The other AI-kit
 * components apply this treatment inline; this frame lets ANY content (a summary, a table, a chart)
 * carry the same provenance without re-implementing it.
 *
 * Tokens only. `role="group"` with an accessible label so assistive tech announces the AI origin.
 */
export function AiProvenanceFrame({
  children,
  label = 'AI-generated',
  caveat = true,
  caveatText = 'Verify before acting',
  variant = 'rule',
  className,
}: AiProvenanceFrameProps): JSX.Element {
  return (
    <div
      className={['ha-provenance', `ha-provenance--${variant}`, className].filter(Boolean).join(' ')}
      role="group"
      aria-label={`${label} content`}
    >
      <span className="ha-provenance__label">
        <span className="ha-provenance__glyph" aria-hidden="true">✦</span>
        {label}
      </span>
      <div className="ha-provenance__body">{children}</div>
      {caveat && <span className="ha-provenance__caveat">{caveatText}</span>}
    </div>
  );
}
